def db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    return con

def init_db():
    con = db()
    con.execute("""CREATE TABLE IF NOT EXISTS users(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL,
        created_at TEXT NOT NULL
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS profiles(
        user_id INTEGER PRIMARY KEY,
        name TEXT, age INTEGER, gender TEXT, height REAL, weight REAL,
        goal TEXT, activity TEXT, diet TEXT, allergies TEXT
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS messages(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        role TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at TEXT NOT NULL
    )""")
    con.commit()
    con.close()

def save_message(user_id, role, content):
    con = db()
    con.execute(
        "INSERT INTO messages(user_id,role,content,created_at) VALUES(?,?,?,?)",
        (user_id, role, content, datetime.now().isoformat(timespec="seconds"))
    )
    con.commit()
    con.close()

def load_history(user_id):
    con = db()
    rows = con.execute(
        "SELECT role,content FROM messages WHERE user_id=? ORDER BY id",
        (user_id,)
    ).fetchall()
    con.close()
    return [{"role": r["role"], "content": r["content"]} for r in rows]

def login(username, password):
    con = db()
    row = con.execute(
        "SELECT * FROM users WHERE username=? AND password=?",
        (username, password)
    ).fetchone()
    con.close()
    return row

def register(username, password):
    try:
        con = db()
        cur = con.execute(
            "INSERT INTO users(username,password,created_at) VALUES(?,?,?)",
            (username, password, datetime.now().isoformat(timespec="seconds"))
        )
        con.commit()
        uid = cur.lastrowid
        con.close()
        return uid
    except sqlite3.IntegrityError:
        return None

def get_profile(uid):
    con = db()
    row = con.execute("SELECT * FROM profiles WHERE user_id=?", (uid,)).fetchone()
    con.close()
    return dict(row) if row else {}

def save_profile(uid, data):
    con = db()
    con.execute("""INSERT INTO profiles
        (user_id,name,age,gender,height,weight,goal,activity,diet,allergies)
        VALUES(?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET
        name=excluded.name, age=excluded.age, gender=excluded.gender,
        height=excluded.height, weight=excluded.weight, goal=excluded.goal,
        activity=excluded.activity, diet=excluded.diet, allergies=excluded.allergies
    """, (uid, *data))
    con.commit()
    con.close()

def nutrition_metrics(p):
    h = float(p.get("height") or 0)
    w = float(p.get("weight") or 0)
    age = int(p.get("age") or 0)
    gender = p.get("gender","")
    if not h or not w or not age:
        return None
    bmi = w / ((h/100)**2)
    if gender.lower().startswith("m"):
        bmr = 10*w + 6.25*h - 5*age + 5
    else:
        bmr = 10*w + 6.25*h - 5*age - 161
    factors = {"Low":1.2,"Moderate":1.45,"High":1.65,"Very High":1.85}
    tdee = bmr * factors.get(p.get("activity"),1.45)
    goal = p.get("goal","")
    calories = tdee
    if "Loss" in goal: calories -= 350
    if "Gain" in goal: calories += 300
    protein = w * (1.8 if "Gain" in goal else 1.6)
    return {"bmi":bmi,"bmr":bmr,"tdee":tdee,"calories":calories,"protein":protein}

def openrouter(prompt, profile, image=None, language="English"):
    key = st.secrets.get("OPENROUTER_API_KEY", os.getenv("OPENROUTER_API_KEY",""))
    if not key:
        return "OpenRouter API key is not configured. Add OPENROUTER_API_KEY to Streamlit Secrets or your environment."
    p = profile or {}
    context = f"""
You are Sport Diet Advisor, an AI sports-nutrition coaching assistant.
User profile:
Name: {p.get('name','Not provided')}
Age: {p.get('age','Not provided')}
Gender: {p.get('gender','Not provided')}
Height: {p.get('height','Not provided')} cm
Weight: {p.get('weight','Not provided')} kg
Goal: {p.get('goal','Not provided')}
Activity: {p.get('activity','Not provided')}
Diet: {p.get('diet','Not provided')}
Allergies: {p.get('allergies','None reported')}
Respond in {language}.
Give practical, structured guidance. Respect allergies and dietary preferences.
Do not diagnose medical conditions. For serious symptoms or medical conditions, advise consultation with a qualified professional.
"""
    content = [{"type":"text","text":context + "\nUser request:\n" + prompt}]
    if image is not None:
        buf = io.BytesIO()
        image.save(buf, format="JPEG")
        b64 = base64.b64encode(buf.getvalue()).decode()
        content.append({"type":"image_url","image_url":{"url":f"data:image/jpeg;base64,{b64}"}})
    payload = {
        "model":"openai/gpt-4o-mini",
        "messages":[{"role":"user","content":content}],
        "temperature":0.6,
        "max_tokens":1200
    }
    r = requests.post(
        "https://openrouter.ai/api/v1/chat/completions",
        headers={"Authorization":f"Bearer {key}","Content-Type":"application/json"},
        json=payload, timeout=90
    )
    r.raise_for_status()
    return r.json()["choices"][0]["message"]["content"]

